-- Insert Quiz Questions for Lesson: Create an Email Campaign

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 3 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 3 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-email-campaign' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-email-campaign not found in module 3';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where do you go to create an email campaign in LeadProspectrr?', 
    '["Contacts > Import","Marketing > Email Campaigns","Settings > Users","Dashboard > Analytics"]'::jsonb,
    'Marketing > Email Campaigns',
    'Email campaigns are created in the Marketing section under Email Campaigns, separate from where you create templates.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before sending a campaign to your full list?', 
    '["Post about it on social media","Send a test email to yourself first","Delete your contact list","Wait for a holiday"]'::jsonb,
    'Send a test email to yourself first',
    'Always send yourself a test email to check formatting, links, personalization, and how it appears on different devices before sending to your full audience.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why shouldn''t you send every campaign to your entire contact list?', 
    '["It costs more money","Not everyone is interested in every message, which can lead to unsubscribes","The system won''t allow it","It takes longer to send"]'::jsonb,
    'Not everyone is interested in every message, which can lead to unsubscribes',
    'Sending irrelevant emails to your entire list leads to lower engagement and higher unsubscribe rates. Use smart lists to send the right message to the right people.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
